  "implementation": "def solve(case):
    if isinstance(case, dict) and 'segments' in case:
        payload = case
    else:
        payload = case.get('payload')
        if payload is None:
            raise ValueError('Missing payload')
    segments = payload.get('segments')
    budget = payload.get('budget')
    if not segments or budget is None:
        raise ValueError('Invalid case')
    names = []
    importances = []
    minimums = []
    capacities = []
    for seg in segments:
        name = seg.get('name')
        importance = seg.get('importance')
        minimum = seg.get('minimum')
        capacity = seg.get('capacity')
        if any(v is None for v in (name, importance, minimum, capacity)):
            raise ValueError('Missing segment field')
        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)
    total_min = sum(minimums)
    total_cap = sum(capacities)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of feasible range')
    alloc = list(minimums)
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_val = -1.0
        for i in range(len(segments)):
            if alloc[i] < capacities[i]:
                val = importances[i] / (alloc[i] + 1)
                if best_idx == -1 or val > best_val or (val == best_val and i < best_idx):
                    best_val = val
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    allocations = {names[i]: alloc[i] for i in range(len(names))}
    total_allocated = sum(alloc)
    return {
        'allocations': allocations,
        'segments': names,
        'total_allocated': total_allocated
    }
